/* BESTIAIRE — données : oiseaux, reptiles, amphibiens */
window.ANIMAUX = (window.ANIMAUX || []).concat([

/* ============ OISEAUX ============ */

{id:"corbeau-caledonien",nom:"Corbeau de Nouvelle-Calédonie",sci:"Corvus moneduloides",emo:"🐦‍⬛",gr:"Oiseau",ord:"Passeriformes",fam:"Corvidés",bio:"foret",
hab:"Forêts et plantations",rep:"Nouvelle-Calédonie",taille:"40 cm",poidsKg:0.3,vit:null,vie:20,
reg:"Omnivore",uicn:"LC",rar:5,
res:"L'animal non-humain qui fabrique les outils les plus sophistiqués de la planète. Un oiseau au cerveau de la taille d'une noix.",
f:[["Il taille des crochets dans des brindilles et découpe des lamelles dentelées dans les feuilles de pandanus pour extraire des larves du bois mort.","base"],
["Il utilise des méta-outils : il se sert d'un outil court pour attraper un outil long, qu'il utilisera ensuite pour atteindre la nourriture. Résoudre un problème en plusieurs coups d'avance, c'est un niveau que seuls quelques grands singes atteignent.","expert"],
["Une femelle nommée Betty a plié spontanément un fil de fer droit en crochet pour récupérer un seau au fond d'un tube. Elle n'avait jamais vu de fil de fer. C'est de l'innovation, pas de l'imitation.","pointu"],
["Les formes d'outils varient d'une vallée à l'autre et se transmettent de génération en génération, en se perfectionnant : c'est une des seules preuves de culture cumulative hors de notre espèce.","expert"],
["Son cerveau est minuscule mais son pallium — l'équivalent fonctionnel de notre cortex — contient une densité de neurones supérieure à celle des primates. Petit cerveau ne veut pas dire peu de neurones.","expert"]],
v:[["Culture cumulative","Transmission de savoir-faire qui s'améliorent de génération en génération, chacune partant de là où la précédente s'est arrêtée. C'est le moteur de la technique humaine."]],
q:[["Qu'est-ce qu'un méta-outil ?",["Un outil très grand","Un outil servant à obtenir un autre outil","Un outil fabriqué à plusieurs","Un outil en métal"],1,"Le corbeau calédonien planifie deux étapes à l'avance — ce que peu d'animaux font."],
["Pourquoi le petit cerveau du corbeau est-il si performant ?",["Il travaille plus vite","Ses neurones sont plus densément tassés que chez les primates","Il utilise plus d'oxygène","Il est plus plissé"],1,"La taille compte moins que le nombre de neurones et leur organisation."]],
d:["corvides","outils"]},

{id:"grand-corbeau",nom:"Grand corbeau",sci:"Corvus corax",emo:"🐦‍⬛",gr:"Oiseau",ord:"Passeriformes",fam:"Corvidés",bio:"montagne",
hab:"Montagnes, falaises, toundras",rep:"Hémisphère nord",taille:"60 à 70 cm, 1,3 m d'envergure",poidsKg:1.2,vit:70,vie:20,
reg:"Omnivore",uicn:"LC",rar:3,
res:"Le plus grand passereau du monde, et l'un des rares animaux capables de préparer un outil pour un usage qu'il n'aura que le lendemain.",
f:[["Il reconnaît les visages humains individuellement, garde rancune contre celui qui l'a piégé, et prévient ses congénères.","base"],
["Dans une expérience de 2017, des corbeaux ont choisi et gardé un outil pour une tâche qu'ils ne pourraient effectuer que 17 heures plus tard. Ils ont même préféré cet outil à une récompense immédiate. Planifier pour un futur qu'on ne perçoit pas : très peu d'espèces le font.","expert"],
["Quand il cache de la nourriture et qu'un autre corbeau l'observe, il fait de fausses caches pour le tromper. Ce qui suppose de comprendre que l'autre voit — un embryon de théorie de l'esprit.","expert"],
["On les a filmés glissant sur des toits enneigés, se laissant tomber sur le dos, puis remontant pour recommencer. Le jeu gratuit est un bon indicateur d'intelligence.","pointu"],
["Ils guident parfois loups et gloutons vers une carcasse trop dure pour leur bec — puis mangent ce que les carnivores ouvrent. Une alliance qui n'a rien d'un contrat mais qui fonctionne.","pointu"]],
v:[["Théorie de l'esprit","Capacité à comprendre que les autres ont des connaissances et des intentions différentes des siennes. Longtemps considérée comme exclusivement humaine."]],
q:[["Qu'ont démontré les corbeaux dans l'expérience de 2017 ?",["Ils comptent jusqu'à 10","Ils planifient jusqu'à 17 heures à l'avance","Ils parlent","Ils reconnaissent leur reflet"],1,"Ils ont même refusé une friandise immédiate pour garder l'outil utile plus tard."],
["Pourquoi un corbeau fait-il de fausses caches ?",["Par erreur","Pour tromper un congénère qui l'observe","Pour marquer son territoire","Pour tester le sol"],1,"Il agit en fonction de ce que l'autre a pu voir — un signe de théorie de l'esprit."]],
d:["corvides","outils"]},

{id:"kea",nom:"Kéa",sci:"Nestor notabilis",emo:"🦜",gr:"Oiseau",ord:"Psittaciformes",fam:"Nestoridés",bio:"montagne",
hab:"Montagnes alpines",rep:"Île du Sud, Nouvelle-Zélande",taille:"48 cm",poidsKg:0.9,vit:null,vie:20,
reg:"Omnivore",uicn:"EN",rar:4,
res:"Le seul perroquet alpin du monde, et probablement le plus grand vandale du règne animal.",
f:[["Il démonte méthodiquement les voitures des parkings de randonnée : joints de portière, essuie-glaces, antennes. Pas pour manger — pour voir ce qui se passe.","base"],
["Il possède un cri de jeu spécifique. Diffusé en haut-parleur, ce cri déclenche des parties de jeu chez tous les kéas qui l'entendent, même seuls. C'est l'équivalent d'un rire contagieux — le premier documenté chez un oiseau.","expert"],
["Il résout des casse-tête à plusieurs étapes et raisonne sur des probabilités : dans un test de 2020, des kéas ont su choisir le bocal offrant la meilleure chance de tirer un jeton gagnant.","expert"],
["Il vit à 1 500 m d'altitude sous la neige, alors que tous les autres perroquets sont tropicaux.","pointu"]],
v:[["Néophilie","Attirance pour la nouveauté. Elle coûte cher (risque, temps perdu) mais permet d'exploiter des ressources imprévues. Kéas, corbeaux et ratons laveurs en sont pleins."]],
q:[["Qu'a-t-on découvert au sujet du cri de jeu du kéa ?",["Il sert à s'accoupler","Il déclenche le jeu chez les autres, comme un rire contagieux","Il imite les humains","Il fait fuir les prédateurs"],1,"Diffusé en haut-parleur, il suffit à lancer une partie."],
["Qu'est-ce qui rend le kéa unique parmi les perroquets ?",["Il ne vole pas","Il vit en montagne enneigée","Il est carnivore strict","Il est nocturne"],1,"Le seul perroquet alpin au monde."]],
d:["corvides","outils"]},

{id:"cacatoes-goffin",nom:"Cacatoès de Goffin",sci:"Cacatua goffiniana",emo:"🦜",gr:"Oiseau",ord:"Psittaciformes",fam:"Cacatuidés",bio:"jungle",
hab:"Forêts et lisières",rep:"Îles Tanimbar, Indonésie",taille:"31 cm",poidsKg:0.3,vit:null,vie:25,
reg:"Granivore",uicn:"NT",rar:4,
res:"Un perroquet qui n'utilise pas d'outils dans la nature — mais qui en invente quand on lui pose un problème. Et qui a appris à toute une ville à ouvrir les poubelles.",
f:[["Un mâle nommé Figaro a spontanément découpé des échardes de bois pour attraper une noix hors de portée, sans qu'aucun cacatoès de son espèce ne l'ait jamais fait.","base"],
["En 2021, on a montré qu'ils transportent une véritable trousse à outils : pour ouvrir une noix de mer, il faut un coin, un couteau et une cuillère. Ils emportent les trois d'un coup s'ils savent qu'ils devront voler jusqu'à la cible. Anticiper le besoin d'un outil qu'on n'a pas encore utilisé, c'est du niveau des chimpanzés.","expert"],
["À Sydney, des cacatoès à huppe jaune — espèce cousine — ont appris à soulever les couvercles de poubelles. La technique s'est propagée de quartier en quartier, avec des variantes locales : de la culture urbaine, cartographiée en direct par les scientifiques.","pointu"],
["Les humains ont riposté avec briques et fils tendus, les oiseaux ont contourné. On appelle ça une course aux armements comportementale.","pointu"]],
v:[["Innovation comportementale","Comportement nouveau inventé par un individu, qui peut ensuite se diffuser dans la population. C'est le point de départ de toute culture animale."]],
q:[["Qu'a montré l'expérience de la « trousse à outils » de 2021 ?",["Les cacatoès imitent les humains","Ils transportent d'avance les outils dont ils auront besoin","Ils fabriquent des outils en métal","Ils travaillent en équipe"],1,"Anticipation : ils emportent les trois outils s'ils savent qu'ils devront voler jusqu'à la tâche."],
["Comment la technique d'ouverture des poubelles s'est-elle répandue à Sydney ?",["Génétiquement","Par apprentissage social, de quartier en quartier","Par hasard simultané","Elle a été enseignée par des humains"],1,"Avec des variantes régionales : le signe d'une transmission culturelle."]],
d:["outils","corvides"]},

{id:"manchot-empereur",nom:"Manchot empereur",sci:"Aptenodytes forsteri",emo:"🐧",gr:"Oiseau",ord:"Sphenisciformes",fam:"Sphéniscidés",bio:"polaire",
hab:"Banquise antarctique",rep:"Antarctique",taille:"1,1 à 1,3 m",poidsKg:35,vit:36,vie:20,
reg:"Piscivore",uicn:"NT",rar:4,
res:"Le seul animal qui se reproduit en plein hiver antarctique, dans le noir, à −60 °C, sur une glace flottante.",
f:[["La femelle pond un unique œuf puis part en mer. Le mâle le garde sur ses pattes, sous un repli de peau, pendant 65 jours sans rien manger : il perd près de la moitié de son poids.","base"],
["Les mâles forment une « tortue » de plusieurs milliers d'individus serrés. À l'intérieur, il fait jusqu'à +37 °C. Et le groupe tourne lentement : chacun passe à son tour au centre et en bordure. Personne ne dirige — la rotation émerge de micro-déplacements de quelques centimètres qui se propagent comme une onde.","expert"],
["Il plonge à plus de 500 m et tient jusqu'à 27 minutes en apnée : le record absolu chez les oiseaux.","pointu"],
["Ses plumes, quatre fois plus denses que celles d'un oiseau volant, sont doublées d'un duvet et enduites d'huile. Un manchot mouillé jusqu'à la peau meurt.","pointu"],
["Son sang tolère des taux d'acide lactique et un manque d'oxygène qui provoqueraient une perte de connaissance chez nous.","expert"]],
v:[["Auto-organisation","Ordre collectif né sans chef ni plan, à partir de règles locales simples suivies par chaque individu. Vol des étourneaux, banc de poissons, tortue de manchots."]],
q:[["Qui couve l'œuf du manchot empereur ?",["La femelle","Le mâle, seul, pendant 65 jours","Les deux en alternance","Un couple voisin"],1,"La femelle part se nourrir en mer et revient nourrir le poussin."],
["Comment la « tortue » de manchots répartit-elle la chaleur ?",["Un chef organise la rotation","Elle tourne toute seule par propagation de micro-déplacements","Les plus faibles restent au centre","Elle ne tourne pas"],1,"De l'auto-organisation : personne ne décide, l'ordre émerge."]],
d:["extremes","records"]},

{id:"albatros-hurleur",nom:"Albatros hurleur",sci:"Diomedea exulans",emo:"🕊️",gr:"Oiseau",ord:"Procellariiformes",fam:"Diomédéidés",bio:"ocean",
hab:"Océan austral",rep:"Autour de l'Antarctique",taille:"1,1 m, 3,5 m d'envergure",poidsKg:9,vit:127,vie:50,
reg:"Carnivore",uicn:"VU",rar:4,
res:"La plus grande envergure du monde vivant. Un oiseau qui parcourt des milliers de kilomètres sans presque battre des ailes.",
f:[["Son envergure atteint 3,5 m — record absolu chez les oiseaux actuels.","base"],
["Il pratique le vol dynamique : il exploite la différence de vitesse du vent entre la surface de la mer et 15 m d'altitude, puisant de l'énergie dans ce gradient à chaque virage. Son rythme cardiaque en vol est à peine plus élevé qu'au repos. Il peut faire le tour du globe en 46 jours.","expert"],
["Les couples restent ensemble à vie et se retrouvent chaque saison sur le même mètre carré de falaise, après des mois séparés à l'autre bout de l'océan.","base"],
["Il ne se reproduit que tous les deux ans, avec un seul œuf. C'est ce qui rend l'espèce si vulnérable : chaque adulte tué par un hameçon de palangre coûte des décennies de reproduction.","pointu"],
["Sa cousine, l'albatros de Laysan Wisdom, est baguée depuis 1956 : c'est le plus vieil oiseau sauvage connu, et elle pond encore.","pointu"]],
v:[["Vol dynamique","Technique consistant à récupérer de l'énergie dans la différence de vitesse du vent entre deux altitudes. Les planeurs humains s'en inspirent."]],
q:[["Comment l'albatros vole-t-il des milliers de km sans se fatiguer ?",["Il plane sur les courants chauds","Il exploite le gradient de vent au-dessus des vagues","Il se laisse porter par les vagues","Il alterne nage et vol"],1,"Le vol dynamique : son cœur bat presque comme au repos."],
["Tous les combien un albatros hurleur se reproduit-il ?",["Chaque année","Tous les deux ans","Deux fois par an","Une fois dans sa vie"],1,"Un seul œuf tous les deux ans — d'où la fragilité face à la pêche à la palangre."]],
d:["migrations","records"]},

{id:"colibri-roux",nom:"Colibri roux",sci:"Selasphorus rufus",emo:"🐦",gr:"Oiseau",ord:"Apodiformes",fam:"Trochilidés",bio:"foret",
hab:"Prairies fleuries, lisières",rep:"De l'Alaska au Mexique",taille:"8 cm",poidsKg:0.0035,vit:100,vie:8,
reg:"Nectarivore",uicn:"NT",rar:3,
res:"Trois grammes et demi qui parcourent 6 000 km deux fois par an, et qui frôlent la mort chaque nuit — volontairement.",
f:[["C'est le seul groupe d'oiseaux capable de voler en marche arrière et de faire du surplace parfait. Ses ailes décrivent un 8 et produisent de la portance à l'aller comme au retour.","base"],
["En vol, son cœur bat jusqu'à 1 200 fois par minute et ses ailes 50 à 80 fois par seconde.","base"],
["Chaque nuit, il entre en torpeur : sa température chute de 40 °C à environ 18 °C, son cœur ralentit à 50 battements par minute, il devient raide et ne réagit plus. Sans ça, il mourrait de faim avant l'aube.","pointu"],
["Il mémorise chaque fleur visitée et le temps qu'elle met à refaire son nectar, puis organise sa tournée en conséquence. Une carte mentale avec horloge intégrée.","expert"],
["Rapporté à sa taille, sa migration Alaska-Mexique est la plus longue du monde : environ 78 millions de longueurs de corps.","expert"]],
v:[["Torpeur nocturne","Baisse extrême et volontaire du métabolisme pendant quelques heures. Chez le colibri, c'est une nécessité quotidienne : ses réserves ne tiennent pas une nuit."]],
q:[["Que fait un colibri chaque nuit ?",["Il migre","Il entre en torpeur, température divisée par deux","Il mange sans arrêt","Il dort en volant"],1,"Sinon, ses réserves seraient épuisées avant le lever du jour."],
["Quelle capacité de vol le colibri est-il seul à posséder chez les oiseaux ?",["Le vol en piqué","Le vol en marche arrière","Le vol plané","Le vol de nuit"],1,"Ses ailes produisent de la portance dans les deux sens du battement."]],
d:["migrations","records","extremes"]},

{id:"martinet-ventre-blanc",nom:"Martinet à ventre blanc",sci:"Tachymarptis melba",emo:"🐦",gr:"Oiseau",ord:"Apodiformes",fam:"Apodidés",bio:"ciel",
hab:"Falaises, ciel ouvert",rep:"Europe du Sud, Afrique, Asie",taille:"22 cm",poidsKg:0.1,vit:110,vie:20,
reg:"Insectivore",uicn:"LC",rar:4,
res:"Un oiseau qui a documenté 200 jours de vol ininterrompu — sans se poser une seule fois. Il mange, boit, s'accouple et dort en l'air.",
f:[["Des capteurs posés en 2013 ont montré que des martinets à ventre blanc restaient en vol continu 200 jours durant leur migration africaine. Chez le martinet noir, on a mesuré jusqu'à dix mois.","base"],
["Il dort en volant, en montant à 2 000 ou 3 000 m le soir puis en descendant lentement en planant. Une moitié de son cerveau peut rester éveillée : c'est le sommeil unihémisphérique, qu'on trouve aussi chez les dauphins.","expert"],
["Ses pattes sont si réduites qu'il ne peut pas décoller d'un sol plat. Le nom de l'ordre, Apodiformes, signifie « sans pieds ».","pointu"],
["Il boit en effleurant la surface d'un lac à pleine vitesse, et récolte les insectes dans une poche de gorge pour en faire une boulette à rapporter aux petits.","pointu"]],
v:[["Sommeil unihémisphérique","Un hémisphère du cerveau dort pendant que l'autre veille, avec un œil ouvert. Dauphins, otaries, canards et martinets le pratiquent."]],
q:[["Combien de temps un martinet à ventre blanc peut-il rester en vol sans se poser ?",["3 jours","3 semaines","200 jours","5 ans"],2,"Mesuré par capteurs embarqués : il mange, boit, dort et s'accouple en vol."],
["Qu'est-ce que le sommeil unihémisphérique ?",["Dormir debout","Dormir un hémisphère à la fois","Dormir par micro-siestes","Ne jamais rêver"],1,"Un hémisphère veille, un œil reste ouvert."]],
d:["records","migrations"]},

{id:"sterne-arctique",nom:"Sterne arctique",sci:"Sterna paradisaea",emo:"🐦",gr:"Oiseau",ord:"Charadriiformes",fam:"Laridés",bio:"polaire",
hab:"Côtes et haute mer",rep:"Pôle à pôle",taille:"33 à 39 cm",poidsKg:0.11,vit:40,vie:30,
reg:"Piscivore",uicn:"LC",rar:3,
res:"La plus longue migration du monde animal : elle vit dans deux étés, à chaque bout de la planète.",
f:[["Elle niche en Arctique l'été boréal, puis file passer l'été austral en Antarctique. Aller-retour : 70 000 à 90 000 km par an, avec un record mesuré à 96 000 km.","base"],
["Sur une vie de 30 ans, elle parcourt environ 2,4 millions de kilomètres — trois allers-retours Terre-Lune.","pointu"],
["Elle ne vole pas en ligne droite : elle suit des boucles en S pour exploiter les vents dominants, quitte à rallonger de milliers de kilomètres. Plus long, mais moins coûteux.","expert"],
["Vivant dans deux étés polaires, c'est l'animal qui voit le plus de lumière du jour de toute la planète.","base"]],
v:[["Migration","Déplacement saisonnier régulier entre deux zones, généralement pour suivre la nourriture ou la reproduction. Elle suppose une orientation fiable : soleil, étoiles, champ magnétique."]],
q:[["Quelle distance parcourt une sterne arctique chaque année ?",["7 000 km","20 000 km","70 000 à 90 000 km","500 000 km"],2,"Pôle à pôle et retour, chaque année de sa vie."],
["Pourquoi la sterne ne vole-t-elle pas en ligne droite ?",["Pour éviter les prédateurs","Pour exploiter les vents dominants","Pour trouver des îles","Pour suivre les côtes"],1,"Un détour aérodynamique coûte moins cher qu'un trajet direct contre le vent."]],
d:["migrations","records"]},

{id:"faucon-pelerin",nom:"Faucon pèlerin",sci:"Falco peregrinus",emo:"🦅",gr:"Oiseau",ord:"Falconiformes",fam:"Falconidés",bio:"ciel",
hab:"Falaises, gratte-ciel",rep:"Tous les continents sauf l'Antarctique",taille:"38 à 50 cm",poidsKg:0.9,vit:389,vie:15,
reg:"Carnivore",uicn:"LC",rar:3,
res:"L'animal le plus rapide de la planète — mais uniquement en tombant. Et l'un des plus beaux sauvetages de l'histoire de la conservation.",
f:[["En piqué, il atteint 389 km/h, vitesse mesurée. En vol battu, il plafonne vers 110 km/h : son record est celui d'une chute contrôlée.","base"],
["À cette vitesse, l'air entrerait dans ses poumons avec une force destructrice. Des tubercules osseux dans ses narines brisent le flux d'air. On raconte souvent qu'ils ont inspiré les entrées d'air des réacteurs — la ressemblance est frappante, mais la filiation historique est douteuse. Méfie-toi des bonnes histoires.","expert"],
["Sa vision est huit fois plus précise que la nôtre : il repère un pigeon à 3 km. Une membrane transparente, la nictitante, essuie son œil en plein piqué.","pointu"],
["Le DDT amincissait la coquille de ses œufs, qui se brisaient sous le poids des parents. L'espèce a disparu de l'est des États-Unis dans les années 1960. Après l'interdiction du DDT et un vaste programme de réintroduction, elle est revenue partout — y compris sur les gratte-ciel, où les pigeons remplacent les proies de falaise.","pointu"]],
v:[["Bioaccumulation","Concentration croissante d'un polluant à mesure qu'on monte dans la chaîne alimentaire. Le DDT était dilué dans l'eau, massif chez les prédateurs de sommet."]],
q:[["Quelle est la vitesse maximale du faucon pèlerin ?",["120 km/h","250 km/h","389 km/h","500 km/h"],2,"En piqué uniquement. En vol battu, il est bien plus lent qu'un martinet."],
["Pourquoi le faucon pèlerin a-t-il failli disparaître ?",["La chasse","Le DDT fragilisait la coquille de ses œufs","La disparition des pigeons","Une maladie"],1,"Un polluant concentré par la chaîne alimentaire jusqu'au prédateur de sommet."]],
d:["records","retour"]},

{id:"gypaete-barbu",nom:"Gypaète barbu",sci:"Gypaetus barbatus",emo:"🦅",gr:"Oiseau",ord:"Accipitriformes",fam:"Accipitridés",bio:"montagne",
hab:"Hautes montagnes",rep:"Pyrénées, Alpes, Himalaya, Afrique de l'Est",taille:"1,1 m, 2,8 m d'envergure",poidsKg:6,vit:130,vie:40,
reg:"Ostéophage",uicn:"NT",rar:5,
res:"Le seul vertébré au monde dont le régime est composé presque exclusivement d'os. Et le seul oiseau connu qui se maquille.",
f:[["Les os représentent 70 à 85 % de son alimentation. Son estomac a un pH proche de 1 : il dissout un os en 24 heures.","base"],
["Les os trop gros, il les emporte à 50 ou 100 m de haut et les lâche sur des dalles rocheuses qu'il réutilise pendant des années — ses « ossuaires ». Les jeunes mettent plusieurs saisons à maîtriser le geste.","pointu"],
["Il se baigne dans des sources chargées d'oxyde de fer pour teindre son plumage blanc en orange rouille. Ce n'est ni du camouflage ni un hasard : c'est un signal social, et les individus dominants sont les plus colorés. Aucun autre oiseau ne fait ça.","expert"],
["Exterminé des Alpes au début du XXᵉ siècle — on l'accusait d'enlever des agneaux et des enfants — il y a été réintroduit à partir de 1986. Plus de 300 individus y volent aujourd'hui.","pointu"]],
v:[["Ostéophage","Qui mange des os. Le gypaète est le seul vertébré à en faire son régime principal ; la moelle est très riche en graisse et personne d'autre ne vient la disputer."]],
q:[["De quoi se nourrit principalement le gypaète barbu ?",["De charognes fraîches","D'os","D'agneaux vivants","De poissons"],1,"70 à 85 % d'os : une niche alimentaire que personne d'autre n'occupe."],
["Pourquoi le gypaète se baigne-t-il dans la boue ferrugineuse ?",["Pour se débarrasser des parasites","Pour teindre son plumage : c'est un signal social","Pour se camoufler","Pour se refroidir"],1,"Les individus dominants sont les plus orangés."]],
d:["retour","records"]},

{id:"chouette-effraie",nom:"Chouette effraie",sci:"Tyto alba",emo:"🦉",gr:"Oiseau",ord:"Strigiformes",fam:"Tytonidés",bio:"ville",
hab:"Granges, clochers, campagne ouverte",rep:"Presque toute la planète",taille:"34 cm",poidsKg:0.35,vit:80,vie:10,
reg:"Carnivore",uicn:"LC",rar:2,
res:"Capable de tuer une souris dans l'obscurité totale, au son seul, en trois dimensions. L'un des systèmes auditifs les plus précis jamais mesurés.",
f:[["Ses deux oreilles ne sont pas à la même hauteur : l'une est plus haute que l'autre. Le décalage entre le son perçu à gauche et à droite lui donne la direction horizontale ; le décalage haut-bas lui donne l'altitude. Elle localise donc une proie en 3D, à l'oreille seule.","expert"],
["Son disque facial en forme de cœur n'est pas décoratif : c'est une parabole qui concentre le son vers ses oreilles, avec un gain d'environ 20 décibels.","pointu"],
["Le bord de ses plumes est frangé comme un peigne, ce qui brise les turbulences. Son vol est quasi inaudible — pour sa proie comme pour elle-même, ce qui est aussi important : le bruit de ses propres ailes masquerait les sons qu'elle écoute.","expert"],
["Elle avale ses proies entières et régurgite une pelote d'os et de poils. Disséquer ces pelotes permet de recenser les micromammifères d'une région sans piéger un seul animal.","base"],
["Un couple consomme environ 3 000 rongeurs par an. Beaucoup d'agriculteurs installent des nichoirs plutôt que d'utiliser des raticides.","base"]],
v:[["Disque facial","Couronne de plumes rigides autour de la face des rapaces nocturnes, qui fonctionne comme une antenne parabolique acoustique."]],
q:[["Pourquoi les oreilles de l'effraie sont-elles asymétriques ?",["Pour entendre plus fort","Pour localiser un son en hauteur, pas seulement à gauche/droite","Pour équilibrer sa tête","C'est une malformation"],1,"L'asymétrie verticale lui donne la troisième dimension."],
["Que peut-on apprendre en disséquant une pelote de réjection ?",["L'âge de l'oiseau","La liste des micromammifères de la région","Son sexe","Sa distance de vol"],1,"Un inventaire de la faune locale sans piéger un seul animal."]],
d:["sens","records"]},

{id:"oiseau-lyre",nom:"Ménure superbe (oiseau-lyre)",sci:"Menura novaehollandiae",emo:"🐦",gr:"Oiseau",ord:"Passeriformes",fam:"Ménuridés",bio:"foret",
hab:"Forêts humides",rep:"Sud-est de l'Australie",taille:"80 à 100 cm avec la queue",poidsKg:1,vit:null,vie:30,
reg:"Insectivore",uicn:"LC",rar:4,
res:"Le meilleur imitateur du règne animal. Il reproduit non seulement les chants d'une vingtaine d'espèces, mais l'ambiance sonore entière d'une forêt.",
f:[["Il imite plus de vingt espèces d'oiseaux, et enchaîne les chants avec un réalisme qui trompe les oiseaux eux-mêmes.","base"],
["Sa syrinx — l'organe vocal des oiseaux, situé plus bas que notre larynx — a une musculature simplifiée, ce qui lui donne paradoxalement plus de liberté acoustique.","pointu"],
["Les vidéos d'oiseaux-lyres imitant tronçonneuses et déclencheurs d'appareils photo sont célèbres. La plupart des cas bien documentés concernent des oiseaux captifs ayant vécu près d'humains. Dans la nature, l'imitation de machines est bien plus rare que la légende ne le dit — bon réflexe : demander toujours d'où vient l'enregistrement.","expert"],
["En parade, le mâle produit un « chant d'alarme » factice imitant une nuée d'oiseaux qui fuient un prédateur, au moment précis où la femelle pourrait partir. Il la fait rester par la peur. On appelle ça de la manipulation acoustique.","expert"]],
v:[["Syrinx","Organe vocal des oiseaux, situé à la jonction des bronches. Ses deux branches peuvent vibrer indépendamment : certains oiseaux chantent deux mélodies à la fois."]],
q:[["Qu'est-ce que la syrinx ?",["Une plume de queue","L'organe vocal des oiseaux","Une glande","Un os du crâne"],1,"Elle est située plus bas que notre larynx, à la jonction des bronches."],
["Que faut-il penser des vidéos d'oiseau-lyre imitant une tronçonneuse ?",["C'est courant dans la nature","Ce sont surtout des oiseaux ayant vécu près d'humains","C'est un montage systématique","Ils imitent seulement d'autres oiseaux"],1,"Vérifier la provenance d'un enregistrement fait partie du métier."]],
d:["camouflage"]},

{id:"jardinier-satine",nom:"Jardinier satiné",sci:"Ptilonorhynchus violaceus",emo:"🐦",gr:"Oiseau",ord:"Passeriformes",fam:"Ptilonorhynchidés",bio:"foret",
hab:"Forêts humides et lisières",rep:"Est de l'Australie",taille:"30 cm",poidsKg:0.2,vit:null,vie:20,
reg:"Frugivore",uicn:"LC",rar:4,
res:"Un oiseau qui construit une architecture qu'il n'habite pas, la décore, la peint — et qui utilise l'illusion d'optique pour séduire.",
f:[["Le mâle bâtit un « berceau » : deux murs de brindilles formant une allée. Il n'y niche pas. C'est une scène de spectacle, uniquement destinée à la parade.","base"],
["Il décore l'entrée d'objets exclusivement bleus : plumes de perruche, baies, et aujourd'hui bouchons, pinces à linge, pailles. Les mâles se volent mutuellement leurs collections.","base"],
["Il « peint » les parois avec un mélange de salive et de fruits écrasés, parfois appliqué à l'aide d'un tampon d'écorce tenu dans le bec — un outil.","pointu"],
["Le grand jardinier, une espèce cousine, dispose ses cailloux du plus petit au plus grand en s'éloignant de l'allée. Vue depuis le point où se tient la femelle, cette gradation crée une perspective forcée qui fait paraître l'ensemble plus régulier — et le mâle plus grand. Si on mélange les cailloux, il reconstruit l'illusion en trois jours.","expert"]],
v:[["Sélection sexuelle","Évolution de traits qui ne servent pas à survivre mais à séduire. Elle peut produire des ornements coûteux et absurdes — queue du paon, berceau du jardinier."]],
q:[["À quoi sert le « berceau » du jardinier satiné ?",["À nicher","À la parade nuptiale uniquement","À stocker de la nourriture","À se protéger des prédateurs"],1,"Une scène de spectacle : les œufs sont pondus ailleurs, dans un nid ordinaire."],
["Qu'est-ce que la perspective forcée du grand jardinier ?",["Un chant trompeur","Un rangement des cailloux qui crée une illusion d'optique","Un miroir naturel","Un jeu de lumière"],1,"Il exploite la géométrie du regard de la femelle."]],
d:["outils"]},

{id:"harpie-feroce",nom:"Harpie féroce",sci:"Harpia harpyja",emo:"🦅",gr:"Oiseau",ord:"Accipitriformes",fam:"Accipitridés",bio:"jungle",
hab:"Canopée de forêt tropicale",rep:"Amérique centrale et du Sud",taille:"90 à 105 cm, 2 m d'envergure",poidsKg:9,vit:80,vie:35,
reg:"Carnivore",uicn:"VU",rar:5,
res:"Le rapace le plus puissant du monde. Ses serres sont plus longues que les griffes d'un grizzly, et il chasse des singes en pleine canopée.",
f:[["Ses serres atteignent 13 cm, plus longues que les griffes d'un ours brun. Sa prise exerce une pression capable de broyer des os.","base"],
["Il emporte des proies de 7 à 9 kg — paresseux, singes hurleurs, coatis — soit à peu près son propre poids.","base"],
["Ses ailes sont courtes et larges pour un rapace de cette taille : c'est un avion de forêt, conçu pour virer entre les troncs plutôt que planer haut.","pointu"],
["Un couple n'élève qu'un poussin tous les deux à trois ans, et le jeune reste dépendant près d'un an. Toute perte d'adulte est difficilement compensée : c'est pourquoi la déforestation la fait reculer si vite.","pointu"]],
v:[["Prédateur apical","Espèce au sommet de sa chaîne alimentaire, sans prédateur naturel adulte. Ces espèces sont peu nombreuses, se reproduisent lentement et disparaissent les premières."]],
q:[["Quelle est la longueur des serres d'une harpie ?",["3 cm","6 cm","13 cm","25 cm"],2,"Plus longues que les griffes d'un grizzly."],
["Pourquoi la harpie a-t-elle des ailes courtes et larges ?",["Pour planer haut","Pour manœuvrer entre les arbres","Pour nager","Pour se camoufler"],1,"C'est un chasseur de canopée, pas un planeur de plaine."]],
d:["records"]},

{id:"flamant-rose",nom:"Flamant rose",sci:"Phoenicopterus roseus",emo:"🦩",gr:"Oiseau",ord:"Phoenicopteriformes",fam:"Phénicoptéridés",bio:"riviere",
hab:"Lagunes salées, marais",rep:"Afrique, sud de l'Europe, Asie du Sud",taille:"1,2 à 1,5 m",poidsKg:3.5,vit:60,vie:40,
reg:"Filtreur",uicn:"LC",rar:2,
res:"Un oiseau qui mange la tête à l'envers, dont la couleur vient entièrement de son alimentation, et qui produit du lait.",
f:[["Il plonge la tête à l'envers dans l'eau : sa mandibule supérieure est en bas. Sa langue pompe l'eau à travers des lamelles qui retiennent les micro-organismes — un système de filtration convergent avec celui des baleines à fanons.","pointu"],
["Il naît gris. Sa couleur vient des caroténoïdes des micro-algues et des artémias qu'il filtre. En captivité mal nourri, il redevient blanc.","base"],
["Les deux parents produisent un « lait de jabot » rouge vif, riche en graisse et en protéines, sécrété par leur tube digestif. Les parents pâlissent en nourrissant leur poussin : ils lui transfèrent littéralement leur couleur.","expert"],
["Il tient sur une patte parce que cette position, verrouillée passivement par son anatomie, ne coûte aucun effort musculaire — un flamant mort peut rester debout sur une patte.","expert"],
["Certains lacs où il niche sont si alcalins et si chauds qu'ils brûleraient la peau humaine. Ses pattes ont une peau épaisse qui le protège.","pointu"]],
v:[["Caroténoïde","Pigment orangé fabriqué par les végétaux et certaines algues. Les animaux ne savent pas le produire : ils doivent le manger. C'est ce qui rend la couleur d'un flamant honnête — elle prouve qu'il mange bien."]],
q:[["D'où vient la couleur rose du flamant ?",["De ses gènes","Des caroténoïdes de son alimentation","Du soleil","De ses plumes de mue"],1,"Il naît gris. Mal nourri, il repâlit."],
["Qu'est-ce que le « lait de jabot » ?",["Du lait maternel","Une sécrétion nourrissante produite par les deux parents","De l'eau régurgitée","Une bouillie de graines"],1,"Les parents perdent leur couleur en la transférant au poussin."]],
d:["convergence","extremes"]},

{id:"casoar",nom:"Casoar à casque",sci:"Casuarius casuarius",emo:"🦖",gr:"Oiseau",ord:"Casuariiformes",fam:"Casuariidés",bio:"jungle",
hab:"Forêt tropicale humide",rep:"Nouvelle-Guinée, nord-est de l'Australie",taille:"1,5 à 1,8 m",poidsKg:60,vit:50,vie:40,
reg:"Frugivore",uicn:"LC",rar:4,
res:"Le dinosaure le plus convaincant encore vivant. Réputé l'oiseau le plus dangereux du monde — et pourtant, une pièce maîtresse de la forêt.",
f:[["Sa griffe centrale mesure jusqu'à 12 cm et il détend la patte d'un coup de pied capable d'ouvrir un ventre. Les attaques mortelles sont rares mais documentées.","base"],
["Les oiseaux sont des dinosaures théropodes : ce n'est pas une image, c'est une classification. Le casoar rend cette parenté visible mieux que n'importe quel autre.","pointu"],
["Il avale des fruits entiers et les disperse intacts, parfois à des kilomètres. Une centaine d'espèces d'arbres dépendent presque uniquement de lui pour se propager : trop gros pour tout autre animal. Sans casoar, ces arbres cessent de se répandre.","expert"],
["Son casque, fait d'une mousse osseuse recouverte de kératine, jouerait un rôle acoustique — il émet des sons très graves, autour de 23 Hz, à la limite de l'audible, qui traversent la végétation dense.","expert"]],
v:[["Espèce ingénieure","Espèce qui modifie physiquement son écosystème et le rend habitable pour d'autres : castor, ver de terre, corail, casoar disperseur de graines."]],
q:[["Pourquoi dit-on que le casoar est un dinosaure ?",["Par ressemblance seulement","Parce que les oiseaux sont des dinosaures théropodes","Parce qu'il est très ancien","C'est une légende"],1,"Une classification, pas une métaphore : les oiseaux sont la lignée survivante des théropodes."],
["Quel rôle écologique majeur joue le casoar ?",["Prédateur de sommet","Disperseur de grosses graines","Pollinisateur","Nettoyeur de charognes"],1,"Une centaine d'espèces d'arbres n'ont que lui pour transporter leurs fruits."]],
d:["taxo","symbiose"]},

/* ============ REPTILES ============ */

{id:"dragon-komodo",nom:"Dragon de Komodo",sci:"Varanus komodoensis",emo:"🦎",gr:"Reptile",ord:"Squamata",fam:"Varanidés",bio:"savane",
hab:"Savanes sèches et forêts",rep:"Îles de la Sonde, Indonésie",taille:"2,5 à 3 m",poidsKg:80,vit:20,vie:30,
reg:"Carnivore",uicn:"EN",rar:5,
res:"Le plus grand lézard du monde. Un prédateur venimeux, blindé d'os, dont les femelles peuvent se reproduire seules.",
f:[["On a longtemps enseigné qu'il tuait par infection : sa gueule aurait grouillé de bactéries mortelles. Cette théorie est aujourd'hui abandonnée. En 2009, on a découvert qu'il possède de véritables glandes à venin, dont les toxines empêchent la coagulation et font chuter la tension. La proie meurt d'hémorragie et de choc.","expert"],
["Sa peau contient un maillage d'ostéodermes, de petits os intégrés dans le derme. Des scanners de 2019 ont révélé une véritable cotte de mailles osseuse, absente chez les jeunes et qui s'épaissit avec l'âge. Contre quoi ? Contre les autres dragons de Komodo : ils sont leur propre principal danger.","expert"],
["Plusieurs femelles isolées ont pondu des œufs fertiles sans mâle : c'est la parthénogenèse. Particularité de leur système sexuel, tous les petits nés ainsi sont des mâles.","pointu"],
["Sa langue fourchue collecte des molécules et les porte à l'organe de Jacobson, au palais. Les deux pointes donnent une lecture stéréo : il sait de quel côté vient l'odeur. Il détecte une carcasse à 9 km.","pointu"],
["Les jeunes vivent dans les arbres pendant deux ans et se roulent dans les excréments pour éviter d'être mangés par les adultes.","base"]],
v:[["Parthénogenèse","Reproduction sans fécondation : un œuf se développe seul. Documentée chez des varans, des serpents, des requins et des oiseaux en captivité."]],
q:[["Comment le dragon de Komodo tue-t-il réellement ses proies ?",["Par les bactéries de sa gueule","Par un venin anticoagulant","Par étranglement","Par empoisonnement alimentaire"],1,"La théorie bactérienne a été réfutée : il possède de vraies glandes à venin."],
["Contre quel danger sert son armure d'ostéodermes ?",["Les buffles","Les autres dragons de Komodo","Les humains","Les chutes de pierres"],1,"Elle apparaît à l'âge adulte, quand les combats entre congénères commencent."]],
d:["venins","records"]},

{id:"cameleon-panthere",nom:"Caméléon panthère",sci:"Furcifer pardalis",emo:"🦎",gr:"Reptile",ord:"Squamata",fam:"Chaméléonidés",bio:"jungle",
hab:"Forêts et broussailles côtières",rep:"Nord de Madagascar",taille:"40 à 50 cm",poidsKg:0.18,vit:null,vie:7,
reg:"Insectivore",uicn:"LC",rar:3,
res:"Il ne change pas de couleur pour se camoufler — c'est un mythe tenace. Il parle en couleurs, et il le fait avec des cristaux.",
f:[["Il ne possède aucun pigment bleu ni vert. Sa peau contient une couche de nanocristaux de guanine dont il modifie l'espacement en contractant ses cellules : cela change la longueur d'onde réfléchie. Il ne se colore pas, il règle un filtre optique. Découvert en 2015.","expert"],
["Le changement de couleur sert surtout à communiquer — humeur, dominance, séduction — et à réguler sa température, pas à se cacher. Sa couleur de repos, elle, est déjà camouflée.","base"],
["Sa langue part à 1 500 m/s² d'accélération, plus vite qu'un avion de chasse. Elle n'est pas propulsée par un muscle mais par un ressort de collagène chargé à l'avance, puis relâché d'un coup — le muscle a le temps d'accumuler l'énergie, le tir la libère instantanément.","expert"],
["Ses deux yeux bougent indépendamment et lui donnent un champ de 342°. Quand il vise, ils convergent d'un coup pour mesurer la distance en relief.","pointu"],
["Ses pattes ont des doigts soudés en deux paquets opposés : une pince vivante conçue pour les branches.","base"]],
v:[["Iridophore","Cellule de la peau contenant des nanocristaux qui réfléchissent la lumière. Modifier leur espacement change la couleur perçue, sans aucun pigment. C'est de la couleur structurelle, comme sur les ailes de papillon morpho."]],
q:[["Comment le caméléon change-t-il de couleur ?",["Par des pigments","En modifiant l'espacement de nanocristaux","En changeant de peau","Par la température seule"],1,"De la couleur structurelle : il règle un filtre optique, il ne se teint pas."],
["Comment sa langue atteint-elle une telle accélération ?",["Un muscle très puissant","Un ressort de collagène chargé puis relâché","De l'air comprimé","Une contraction du cœur"],1,"Le principe de l'arbalète : charger lentement, libérer d'un coup."]],
d:["camouflage","records"]},

{id:"gecko-tokay",nom:"Gecko tokay",sci:"Gekko gecko",emo:"🦎",gr:"Reptile",ord:"Squamata",fam:"Gekkonidés",bio:"jungle",
hab:"Forêts, maisons",rep:"Asie du Sud-Est",taille:"30 à 40 cm",poidsKg:0.2,vit:null,vie:10,
reg:"Insectivore",uicn:"LC",rar:2,
res:"Il marche au plafond sur du verre lisse sans colle et sans ventouse — grâce à une force qui agit à l'échelle des molécules.",
f:[["Ses doigts portent des lamelles couvertes de millions de poils microscopiques, les setæ, chacun se divisant en centaines de spatules encore plus fines.","base"],
["L'adhérence vient des forces de van der Waals : à quelques nanomètres de distance, deux surfaces s'attirent faiblement. Multiplié par un milliard de points de contact, ça devient énorme. Un gecko pourrait théoriquement soutenir 130 kg avec ses seules pattes.","expert"],
["Le système est directionnel : il colle quand on tire dans un sens, se décroche instantanément dans l'autre. C'est ce qui lui permet de courir au plafond sans perdre de temps à décoller ses doigts.","expert"],
["Ses pattes sont autonettoyantes : les particules de poussière se détachent d'elles-mêmes à chaque pas.","pointu"],
["Son cri, un « to-kay » sonore répété, lui a donné son nom.","base"]],
v:[["Forces de van der Waals","Attraction très faible entre deux molécules proches. Individuellement négligeable, elle devient considérable quand on multiplie les points de contact."]],
q:[["Grâce à quoi le gecko adhère-t-il au verre ?",["Une colle","Des ventouses","Les forces de van der Waals","L'électricité statique"],2,"Des milliards de contacts nanométriques, aucune substance collante."],
["Pourquoi le gecko ne reste-t-il pas collé ?",["Il transpire","L'adhérence est directionnelle","Il se contracte","Il chauffe ses doigts"],1,"Il colle dans un sens, se décroche dans l'autre : il suffit de changer l'angle."]],
d:["records"]},

{id:"taipan-desert",nom:"Taïpan du désert",sci:"Oxyuranus microlepidotus",emo:"🐍",gr:"Reptile",ord:"Squamata",fam:"Élapidés",bio:"desert",
hab:"Plaines argileuses fissurées",rep:"Centre de l'Australie",taille:"1,8 à 2,5 m",poidsKg:2,vit:null,vie:15,
reg:"Carnivore",uicn:"LC",rar:4,
res:"Le venin le plus toxique du monde, porté par un serpent si discret et si peu agressif qu'il n'a jamais tué personne.",
f:[["Une seule morsure injecte de quoi tuer une centaine d'humains adultes, ou 250 000 souris. Son venin est le plus toxique jamais mesuré chez un serpent terrestre.","base"],
["Aucun décès humain n'est documenté. Il vit dans des plaines désertes, fuit le contact, et un sérum existe. Toxicité et dangerosité sont deux choses différentes : le serpent le plus meurtrier au monde est en réalité l'échide carénée, bien moins toxique mais présente partout où vivent les gens.","expert"],
["Son venin combine neurotoxines, myotoxines et facteurs coagulants : il paralyse, détruit les muscles et provoque des caillots. Cette combinaison tue le rat en quelques secondes — nécessaire quand la proie mord en retour dans un espace confiné.","pointu"],
["Il change de couleur avec les saisons : plus sombre en hiver pour capter la chaleur, plus clair en été pour la refléter.","pointu"]],
v:[["DL50","Dose létale médiane : quantité d'une substance qui tue la moitié d'un groupe d'animaux de test. C'est la mesure standard de toxicité — mais elle ne dit rien du risque réel de rencontre."]],
q:[["Pourquoi le taïpan du désert n'a-t-il jamais tué d'humain ?",["Son venin est inefficace sur nous","Il vit dans des zones désertes et fuit le contact","Il n'a pas de crochets","Il n'attaque que la nuit"],1,"Toxicité n'est pas dangerosité : l'échide carénée tue bien plus, avec un venin plus faible."],
["Que mesure la DL50 ?",["La vitesse d'action d'un venin","La dose qui tue la moitié des sujets testés","La quantité injectée par morsure","La douleur ressentie"],1,"Une mesure de toxicité en laboratoire, pas de risque réel."]],
d:["venins"]},

{id:"crocodile-marin",nom:"Crocodile marin",sci:"Crocodylus porosus",emo:"🐊",gr:"Reptile",ord:"Crocodilia",fam:"Crocodylidés",bio:"riviere",
hab:"Estuaires, mangroves, mer côtière",rep:"Inde à l'Australie",taille:"4 à 6 m",poidsKg:1000,vit:29,vie:70,
reg:"Carnivore",uicn:"LC",rar:4,
res:"Le plus grand reptile vivant et la morsure la plus puissante jamais mesurée chez un animal actuel.",
f:[["Sa morsure a été mesurée à 16 460 newtons, soit environ 3 700 livres par pouce carré : plus que le lion, l'hyène ou le requin blanc.","base"],
["Les muscles qui ferment sa gueule sont énormes ; ceux qui l'ouvrent sont si faibles qu'un ruban adhésif suffit à la maintenir close.","base"],
["Ses mâchoires sont criblées de récepteurs de pression capables de détecter une vibration d'eau plus fine que ce que ton doigt peut sentir. Il chasse dans l'eau trouble sans rien voir.","expert"],
["Il traverse des centaines de kilomètres de haute mer, non pas en nageant mais en se laissant porter par les courants de surface : il attend le bon courant, parfois plusieurs jours, puis embarque. Du surf longue distance.","expert"],
["Les crocodiliens ont un cœur à quatre cavités comme les oiseaux et les mammifères, avec en plus une valve qui leur permet de court-circuiter les poumons en plongée.","pointu"]],
v:[["Récepteur de pression dermique","Petit point sensoriel sur la peau des crocodiliens, qui détecte les ondes de pression dans l'eau. Plus sensible que la pulpe d'un doigt humain."]],
q:[["Comment le crocodile marin traverse-t-il l'océan ?",["Il nage sans s'arrêter","Il se laisse porter par les courants de surface","Il marche sur les récifs","Il suit les bateaux"],1,"Il attend le bon courant, parfois plusieurs jours, puis se laisse emporter."],
["Que peut-on dire des muscles de sa gueule ?",["Ils sont puissants dans les deux sens","Fermer est très puissant, ouvrir est très faible","Ils sont lents","Ils fonctionnent hydrauliquement"],1,"Un ruban adhésif suffit à maintenir la gueule d'un crocodile fermée."]],
d:["records","sens"]},

{id:"tortue-luth",nom:"Tortue luth",sci:"Dermochelys coriacea",emo:"🐢",gr:"Reptile",ord:"Testudines",fam:"Dermochélyidés",bio:"ocean",
hab:"Haute mer, plages de ponte tropicales",rep:"Tous les océans",taille:"1,8 à 2,2 m",poidsKg:500,vit:35,vie:50,
reg:"Carnivore",uicn:"VU",rar:5,
res:"La plus grande tortue du monde, la seule sans carapace dure, et l'une des rares à conserver sa chaleur en eau glacée.",
f:[["Sa carapace n'est pas faite d'écailles soudées mais d'une peau épaisse et huileuse renforcée d'ostéodermes en mosaïque. Elle est souple : elle se déforme en plongée profonde au lieu de se briser.","pointu"],
["Elle plonge à 1 280 m, plus profond que la plupart des baleines, et migre jusqu'à 16 000 km entre nourriture et plages de ponte.","base"],
["Elle maintient une température corporelle jusqu'à 18 °C au-dessus de l'eau environnante, dans des mers à 5 °C. Elle y arrive par sa masse, une couche de graisse, des échangeurs à contre-courant dans ses nageoires et sa nage continue. On appelle ça la gigantothermie — une chaleur qu'on doit à sa taille plutôt qu'à un métabolisme.","expert"],
["Sa gorge est tapissée de pointes de kératine tournées vers l'estomac, qui empêchent les méduses de ressortir. C'est aussi ce qui rend un sac plastique avalé impossible à recracher.","expert"],
["Le sexe des petits dépend de la température du sable : plus chaud, plus de femelles. Le réchauffement climatique déséquilibre déjà le sex-ratio de plusieurs populations.","pointu"]],
v:[["Gigantothermie","Stabilité thermique obtenue par la seule taille du corps : plus un animal est gros, plus il perd sa chaleur lentement. Sans doute la solution de certains grands dinosaures."]],
q:[["Comment la tortue luth reste-t-elle chaude en eau froide ?",["Elle a le sang chaud","Par gigantothermie : sa masse et sa graisse retiennent la chaleur","Elle ne le fait pas","Elle remonte en surface"],1,"Une chaleur due à la taille, pas à un métabolisme d'oiseau."],
["Qu'est-ce qui détermine le sexe des jeunes tortues ?",["Les chromosomes","La température du sable","L'ordre de ponte","La profondeur du nid"],1,"Le réchauffement du sable féminise déjà des populations entières."]],
d:["records","migrations","extremes"]},

{id:"tuatara",nom:"Tuatara",sci:"Sphenodon punctatus",emo:"🦎",gr:"Reptile",ord:"Rhynchocephalia",fam:"Sphénodontidés",bio:"foret",
hab:"Îles côtières, terriers partagés",rep:"Nouvelle-Zélande",taille:"50 à 80 cm",poidsKg:1,vit:null,vie:100,
reg:"Carnivore",uicn:"LC",rar:5,
res:"Ce n'est pas un lézard. C'est le dernier survivant d'un ordre entier de reptiles disparu depuis les dinosaures — un rescapé de 200 millions d'années.",
f:[["Il appartient aux rhynchocéphales, un ordre distinct des lézards et serpents. Toutes les autres espèces de cet ordre sont éteintes depuis environ 60 millions d'années. Il est seul de sa lignée.","pointu"],
["Il possède un troisième œil pariétal sur le sommet du crâne, avec cristallin et rétine, recouvert d'écailles chez l'adulte. Il ne forme pas d'image mais règle l'horloge biologique et l'exposition au soleil.","expert"],
["Ses dents ne sont pas des dents mais des pointes de l'os de la mâchoire. Elles ne repoussent pas : un tuatara très âgé mange des proies molles parce qu'il a usé sa mâchoire.","expert"],
["Il reste actif à 5 °C, température à laquelle presque tous les reptiles sont bloqués. Son métabolisme est si lent qu'il respire une fois par heure au repos et vit plus de 100 ans. Un mâle nommé Henry est devenu père à 111 ans.","pointu"],
["Il partage souvent le terrier des puffins et mange parfois leurs poussins. Une colocation à sens unique.","base"]],
v:[["Fossile vivant","Expression commode mais trompeuse : elle désigne une espèce dernière survivante d'un groupe ancien. Elle a continué d'évoluer — le tuatara a même l'un des ADN les plus rapides à muter parmi les vertébrés."]],
q:[["À quel groupe appartient le tuatara ?",["Les lézards","Les rhynchocéphales, dont il est le dernier survivant","Les crocodiliens","Les amphibiens"],1,"Un ordre à part, éteint partout ailleurs depuis 60 millions d'années."],
["Qu'est-ce que son œil pariétal ?",["Un œil de secours","Un troisième œil qui règle son horloge biologique","Une glande","Un organe thermique"],1,"Avec cristallin et rétine, mais recouvert d'écailles chez l'adulte."]],
d:["taxo","records"]},

{id:"iguane-marin",nom:"Iguane marin",sci:"Amblyrhynchus cristatus",emo:"🦎",gr:"Reptile",ord:"Squamata",fam:"Iguanidés",bio:"ocean",
hab:"Côtes rocheuses volcaniques",rep:"Galápagos",taille:"60 à 130 cm",poidsKg:5,vit:null,vie:12,
reg:"Herbivore",uicn:"VU",rar:5,
res:"Le seul lézard marin du monde. Il broute des algues sous l'eau, éternue du sel — et rétrécit quand il a faim.",
f:[["Il plonge jusqu'à 10 m et reste immergé 30 minutes pour brouter les algues des rochers. Aucun autre lézard ne se nourrit en mer.","base"],
["Il avale beaucoup de sel. Des glandes nasales spécialisées le concentrent et il l'expulse en éternuant : d'où la croûte blanche sur sa tête.","base"],
["Pendant les épisodes El Niño, les algues disparaissent et les iguanes peuvent rétrécir jusqu'à 20 % de leur longueur — en résorbant une partie de leur propre squelette. Quand la nourriture revient, ils regrandissent. Aucun autre vertébré adulte ne fait ça.","expert"],
["Sortant d'une eau à 11 °C, il doit se réchauffer au soleil avant de pouvoir digérer. Un iguane trop froid ne peut pas assimiler ce qu'il vient de manger.","pointu"],
["Darwin les a détestés : il les appelait « d'imbéciles lézards ». Ils sont pourtant l'un des meilleurs exemples d'adaptation insulaire qu'il aurait pu citer.","base"]],
v:[["Glande à sel","Organe qui excrète le sel en excès, chez les animaux marins ne pouvant pas compter sur leurs reins. On en trouve chez les oiseaux marins, les tortues et l'iguane marin."]],
q:[["Que font les iguanes marins quand la nourriture manque ?",["Ils hibernent","Ils rétrécissent en résorbant leur squelette","Ils changent de régime","Ils migrent"],1,"Jusqu'à 20 % de leur longueur — et ils regrandissent ensuite."],
["Comment l'iguane marin élimine-t-il le sel ?",["Par ses reins","En éternuant, via des glandes nasales","Par sa peau","Il ne l'élimine pas"],1,"D'où la croûte de sel blanche sur son crâne."]],
d:["extremes","convergence"]},

{id:"cobra-royal",nom:"Cobra royal",sci:"Ophiophagus hannah",emo:"🐍",gr:"Reptile",ord:"Squamata",fam:"Élapidés",bio:"jungle",
hab:"Forêts, bambouseraies",rep:"Inde et Asie du Sud-Est",taille:"3 à 5,5 m",poidsKg:6,vit:18,vie:20,
reg:"Carnivore",uicn:"VU",rar:4,
res:"Le plus long serpent venimeux du monde. Il mange presque exclusivement d'autres serpents — et c'est le seul à construire un nid.",
f:[["Son nom scientifique, Ophiophagus, signifie « mangeur de serpents ». C'est l'essentiel de son régime, y compris d'autres cobras.","base"],
["C'est le seul serpent au monde qui construit un nid : la femelle rassemble des feuilles avec son corps, y pond, et le garde pendant des semaines. La fermentation des feuilles chauffe les œufs.","pointu"],
["Une morsure injecte assez de neurotoxines pour tuer un éléphant. Son venin est moins toxique que celui de nombreux élapidés, mais la quantité — jusqu'à 7 ml — compense largement.","pointu"],
["Menacé, il dresse le tiers avant de son corps, à hauteur d'homme, et émet un son grave évoquant un grognement plutôt qu'un sifflement : il utilise des diverticules trachéaux comme caisses de résonance.","expert"],
["Ce n'est pas un vrai cobra : il forme son propre genre. Les mangoustes le tuent quand même — leurs récepteurs à acétylcholine sont modifiés, ce qui rend la neurotoxine inefficace sur elles.","expert"]],
v:[["Neurotoxine","Toxine qui bloque la transmission entre nerfs et muscles. La victime meurt d'une paralysie respiratoire, en restant consciente."]],
q:[["Que mange principalement le cobra royal ?",["Des rongeurs","D'autres serpents","Des oiseaux","Des grenouilles"],1,"Ophiophagus : « mangeur de serpents »."],
["Pourquoi les mangoustes résistent-elles à son venin ?",["Elles sont trop rapides","Leurs récepteurs à acétylcholine sont modifiés","Elles ont un antidote dans le sang","Leur fourrure les protège"],1,"Une mutation des récepteurs empêche la neurotoxine de s'y fixer."]],
d:["venins","records"]},

/* ============ AMPHIBIENS ============ */

{id:"axolotl",nom:"Axolotl",sci:"Ambystoma mexicanum",emo:"🦎",gr:"Amphibien",ord:"Urodela",fam:"Ambystomatidés",bio:"riviere",
hab:"Canaux et lacs d'altitude",rep:"Xochimilco, Mexico",taille:"20 à 30 cm",poidsKg:0.1,vit:null,vie:15,
reg:"Carnivore",uicn:"CR",rar:5,
res:"Une salamandre qui refuse de grandir, régénère un membre entier en quelques semaines, et a presque disparu de la seule ville où elle vivait.",
f:[["Il est néoténique : il devient adulte et se reproduit tout en gardant ses caractères larvaires — branchies externes, nageoire, vie aquatique. Il ne fait jamais sa métamorphose.","base"],
["Injecte-lui de la thyroxine, l'hormone thyroïdienne, et il se métamorphose : il perd ses branchies et sort de l'eau. La métamorphose n'a pas été perdue, elle a été mise en pause.","expert"],
["Il régénère une patte entière — os, muscles, nerfs, vaisseaux — sans aucune cicatrice, et peut recommencer indéfiniment. Il régénère aussi une partie de son cœur, de sa moelle épinière et de son cerveau.","pointu"],
["Son génome fait 32 milliards de paires de bases, dix fois le nôtre. C'est l'un des plus grands génomes animaux séquencés, ce qui a longtemps freiné son étude.","expert"],
["Il en reste peut-être quelques dizaines à l'état sauvage dans les canaux de Xochimilco, alors que des centaines de milliers vivent en aquarium et en laboratoire. Une espèce éteinte chez elle, prospère ailleurs.","base"]],
v:[["Néoténie","Conservation à l'âge adulte de caractères juvéniles. On soupçonne un rôle de la néoténie dans l'évolution humaine : notre crâne ressemble à celui d'un jeune chimpanzé."]],
q:[["Qu'est-ce que la néoténie chez l'axolotl ?",["Il reste larvaire tout en se reproduisant","Il change de sexe","Il ne vieillit pas","Il pond des œufs vivants"],0,"Branchies externes et vie aquatique conservées à l'âge adulte."],
["Que se passe-t-il si on lui injecte de la thyroxine ?",["Il meurt","Il se métamorphose et sort de l'eau","Il double de taille","Rien"],1,"La métamorphose n'est pas perdue : elle est simplement jamais déclenchée."]],
d:["retour","records"]},

{id:"dendrobate-terrible",nom:"Phyllobate terrible",sci:"Phyllobates terribilis",emo:"🐸",gr:"Amphibien",ord:"Anura",fam:"Dendrobatidés",bio:"jungle",
hab:"Sol de forêt tropicale humide",rep:"Côte pacifique de Colombie",taille:"5 cm",poidsKg:0.03,vit:null,vie:10,
reg:"Insectivore",uicn:"EN",rar:5,
res:"Deux centimètres de peau dorée qui contiennent de quoi tuer dix adultes. Et pourtant, en captivité, elle est parfaitement inoffensive.",
f:[["Sa peau porte de la batrachotoxine, l'un des poisons non protéiques les plus puissants connus. Un individu sauvage en contient assez pour tuer une dizaine de personnes. Le toucher suffit s'il y a une plaie.","base"],
["Elle ne fabrique pas ce poison : elle le récupère dans les petits arthropodes qu'elle mange, sans doute des acariens du sol. Nourrie de grillons d'élevage, une grenouille née en captivité est totalement inoffensive à vie.","expert"],
["Sa couleur jaune vif est un signal d'avertissement — l'aposématisme. Elle ne se cache pas, elle s'affiche : « me manger sera la dernière erreur de ta vie ».","pointu"],
["Les Emberá de Colombie frottaient la pointe de leurs fléchettes sur son dos. Le poison restait actif sur l'arme pendant deux ans.","pointu"],
["Un serpent, Leimadophis epinephelus, est le seul prédateur connu à lui résister — partiellement.","base"]],
v:[["Aposématisme","Coloration voyante qui signale la toxicité. Elle ne fonctionne que si les prédateurs apprennent — donc quelques individus doivent être sacrifiés pour que le message circule."]],
q:[["D'où vient le poison de la phyllobate terrible ?",["Elle le fabrique","De son alimentation sauvage","De son environnement humide","De ses parents"],1,"Née en captivité et nourrie de grillons, elle est parfaitement inoffensive."],
["Qu'est-ce que l'aposématisme ?",["Un camouflage","Une couleur vive signalant la toxicité","Un venin injecté","Un cri d'alarme"],1,"L'inverse du camouflage : se rendre inoubliable."]],
d:["venins","camouflage"]},

{id:"grenouille-de-verre",nom:"Grenouille de verre",sci:"Hyalinobatrachium fleischmanni",emo:"🐸",gr:"Amphibien",ord:"Anura",fam:"Centrolénidés",bio:"jungle",
hab:"Végétation au-dessus des ruisseaux",rep:"Amérique centrale et du Sud",taille:"3 cm",poidsKg:0.002,vit:null,vie:10,
reg:"Insectivore",uicn:"LC",rar:4,
res:"On voit son cœur battre à travers son ventre. Et pour devenir vraiment transparente, elle range son propre sang.",
f:[["Sa peau ventrale est translucide : on distingue le cœur, le foie et les intestins. Vue de dessus, en revanche, elle est verte et banale.","base"],
["Le sang est rouge, donc visible : une grenouille pleine de sang ne peut pas être transparente. En dormant, elle stocke jusqu'à 89 % de ses globules rouges dans son foie, ce qui la rend quasi invisible. Au réveil, elle les relâche.","expert"],
["Concentrer autant de globules rouges devrait provoquer des caillots mortels. Comment elle l'évite reste inexpliqué, et intéresse énormément la recherche sur les thromboses. Découverte publiée en 2022.","expert"],
["Sa transparence ne sert pas à devenir invisible mais à adoucir son contour : la lumière traverse ses bords, sa silhouette se fond dans la feuille. On appelle ça la diffusion des bords.","pointu"],
["Le mâle garde les œufs collés sous une feuille au-dessus d'un ruisseau, et les hydrate en urinant dessus. À l'éclosion, les têtards tombent directement à l'eau.","base"]],
v:[["Transparence adaptative","Stratégie de camouflage par transmission de la lumière. Fréquente en pleine eau (méduses, larves) mais très rare à terre, où le sang et les os la rendent presque impossible."]],
q:[["Comment la grenouille de verre devient-elle transparente en dormant ?",["Elle vide son estomac","Elle stocke ses globules rouges dans son foie","Elle blanchit sa peau","Elle se déshydrate"],1,"Jusqu'à 89 % de ses globules rouges rangés hors de la circulation."],
["Pourquoi cette découverte intéresse-t-elle la médecine ?",["Pour la transparence des tissus","Parce qu'elle évite les caillots là où nous en ferions","Pour la régénération","Pour la vision"],1,"Concentrer autant de sang devrait provoquer une thrombose. Elle ne l'a pas."]],
d:["camouflage"]},

{id:"salamandre-geante-japon",nom:"Salamandre géante du Japon",sci:"Andrias japonicus",emo:"🦎",gr:"Amphibien",ord:"Urodela",fam:"Cryptobranchidés",bio:"riviere",
hab:"Rivières froides et rapides",rep:"Sud-ouest du Japon",taille:"1,2 à 1,5 m",poidsKg:25,vit:null,vie:55,
reg:"Carnivore",uicn:"VU",rar:5,
res:"Le deuxième plus grand amphibien du monde. Elle n'a pas de poumons fonctionnels et respire entièrement par sa peau.",
f:[["Elle atteint 1,5 m et 25 kg, et vit plus de 50 ans — un spécimen captif a dépassé 60 ans.","base"],
["Elle respire par la peau. Les replis et bourrelets de ses flancs augmentent la surface d'échange. Elle a donc besoin d'une eau froide, courante et très oxygénée : réchauffer ou ralentir une rivière suffit à l'étouffer.","pointu"],
["Presque aveugle, elle chasse en détectant les vibrations avec des récepteurs cutanés, puis aspire sa proie par une ouverture brutale de la gueule.","pointu"],
["Menacée, elle sécrète un mucus laiteux à l'odeur de poivre — d'où son surnom japonais, ōsanshōuo, « poisson-poivre géant ».","base"],
["Sa lignée est apparue il y a environ 170 millions d'années et a très peu changé depuis. Des fossiles européens de ce groupe ont été pris au XVIIIᵉ siècle pour les restes d'un humain noyé lors du Déluge.","expert"]],
v:[["Respiration cutanée","Échanges gazeux directement à travers la peau. Elle exige une peau fine et humide — c'est pourquoi les amphibiens sont si sensibles à la pollution : ils respirent leur milieu."]],
q:[["Comment respire la salamandre géante du Japon ?",["Par des branchies","Par la peau","Par des poumons","Par la bouche"],1,"D'où les replis de ses flancs, qui augmentent la surface d'échange."],
["Pourquoi les amphibiens sont-ils de bons indicateurs de pollution ?",["Ils sont rares","Ils respirent et absorbent par la peau","Ils vivent longtemps","Ils migrent beaucoup"],1,"Leur peau perméable les met en contact direct avec toute contamination."]],
d:["taxo","records"]},

{id:"grenouille-des-bois",nom:"Grenouille des bois",sci:"Lithobates sylvaticus",emo:"🐸",gr:"Amphibien",ord:"Anura",fam:"Ranidés",bio:"foret",
hab:"Forêts boréales, toundra",rep:"Amérique du Nord, jusqu'au cercle polaire",taille:"5 à 7 cm",poidsKg:0.008,vit:null,vie:5,
reg:"Insectivore",uicn:"LC",rar:4,
res:"Elle passe l'hiver gelée. Cœur arrêté, cerveau silencieux, deux tiers de son eau transformée en glace — puis elle repart au printemps.",
f:[["En hiver, jusqu'à 65-70 % de l'eau de son corps gèle. Son cœur s'arrête, sa respiration cesse, aucune activité cérébrale n'est mesurable. Sur tous les critères habituels, elle est morte.","base"],
["Son foie convertit massivement le glycogène en glucose et l'injecte dans les cellules : ce sirop concentré empêche la glace de se former à l'intérieur des cellules. La glace se forme entre elles, où elle ne détruit rien.","expert"],
["Elle survit ainsi jusqu'à −18 °C et peut rester gelée plusieurs mois. En Alaska, certaines tiennent sept mois d'affilée en gelant et dégelant plusieurs fois.","pointu"],
["Au dégel, le cœur repart le premier, spontanément, avant même que le reste du corps ne soit décongelé. La recherche sur la cryoconservation d'organes pour la greffe l'étudie de près.","expert"]],
v:[["Cryoprotecteur","Substance qui empêche les cristaux de glace de détruire les cellules. Le glucose chez la grenouille des bois, l'antigel protéique chez les poissons polaires, le glycérol chez certains insectes."]],
q:[["Que devient la grenouille des bois en hiver ?",["Elle hiberne dans la vase","Elle gèle, cœur arrêté","Elle migre au sud","Elle reste active sous la neige"],1,"Deux tiers de son eau corporelle transformée en glace, pendant des mois."],
["Comment évite-t-elle que la glace détruise ses cellules ?",["Elle se déshydrate totalement","Elle sature ses cellules de glucose","Elle produit de la chaleur","Elle s'enterre très profond"],1,"La glace ne se forme qu'entre les cellules, jamais dedans."]],
d:["extremes","records"]}

]);
